#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "doitgen.h"


/* Array initialization. */
static
void init_array(int nr, int nq, int np,
		DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np))
{
  int i, j, k;

  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++)
	A[i][j][k] = (DATA_TYPE) ((i*j + k)%np) / np;
  for (i = 0; i < np; i++)
    for (j = 0; j < np; j++)
      C4[i][j] = (DATA_TYPE) (i*j % np) / np;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original computation, for each (r, q):

     for (p)
       sum[p] = 0;
       for (s)
         sum[p] += A[r][q][s] * C4[s][p];
     for (p)
       A[r][q][p] = sum[p];

   This is a post-multiplication of the row-vector A[r][q][:] by the
   matrix C4 (size np x np).

   Optimization strategy:

   1. Improve data locality and reduce memory traffic:
      - In the original code, A[r][q][s] is reloaded for every p.
        We restructure the loops so that, for a fixed s, we load
        A[r][q][s] once and reuse it across all p.
      - We also make p the innermost loop when accessing C4[s][p].
        Since C4 is stored in row-major order, C4[s][p] is contiguous
        in p, which greatly improves cache and prefetch behavior.

   2. Preserve floating‑point semantics:
      - For each fixed p, the sequence of operations on sum[p]
        still traverses s from 0 to _PB_NP-1 in the same order as
        the original code. We only interleave operations for
        different p values, which are independent. Thus, for each
        p, the order of additions is unchanged, preserving numerical
        behavior as much as possible.

   3. Enable better vectorization:
      - Using contiguous access to C4 rows and keeping independent
        accumulators in sum[p] encourages the compiler’s auto‑
        vectorizer. We also introduce local restrict-qualified
        aliases to help the compiler reason about aliasing.
 */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Create local restrict-qualified aliases with explicit shapes.
     This does not change the ABI but helps the optimizer assume
     that A, C4 and sum do not alias. */
  DATA_TYPE (*restrict A_)[nq][np]   = A;
  DATA_TYPE (*restrict C4_)[np]      = C4;
  DATA_TYPE *restrict sum_           = sum;

#pragma scop
  for (r = 0; r < _PB_NR; r++)
  {
    for (q = 0; q < _PB_NQ; q++)
    {
      /* Initialize the accumulation buffer once per (r, q). */
      for (p = 0; p < _PB_NP; p++)
        sum_[p] = SCALAR_VAL(0.0);

      /* Reordered loops: s outer, p inner.
         For each s, we:
           - load A[r][q][s] once (reused for all p),
           - traverse C4[s][p] contiguously in p. */
      for (s = 0; s < _PB_NP; s++)
      {
        DATA_TYPE a_rqs = A_[r][q][s];
        DATA_TYPE *restrict C4_row = C4_[s];

        /* Inner loop is simple, contiguous, and vectorizable. */
        for (p = 0; p < _PB_NP; p++)
        {
          sum_[p] += a_rqs * C4_row[p];
        }
      }

      /* Write back the result vector into A[r][q][:]. */
      for (p = 0; p < _PB_NP; p++)
        A_[r][q][p] = sum_[p];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}
