      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /*
   * Optimized version:
   *   - Reorders the inner loops to improve spatial locality on C4
   *     (iterate over rows C4[s][:] instead of columns C4[:][p]).
   *   - Uses a per-(r,q) temporary buffer (sum_local) to keep the
   *     working set in L1/L2 and avoid repeated writes to the shared
   *     "sum" array.
   *   - Adds OpenMP parallelism over (r,q) pairs. The pragma is
   *     ignored if the code is compiled without -fopenmp.
   *   - Manually unrolls the innermost p-loop by a factor of 4 to
   *     increase ILP and help auto-vectorization.
   *
   * The mathematical operation remains:
   *   For each (r,q): A[r][q][p] = sum_s A[r][q][s] * C4[s][p]
   *
   * The order of floating-point additions for each output element is
   * preserved (still in increasing s), so numerical results for each
   * A[r][q][p] match the original kernel.
   */

#pragma scop
  /* Parallelize across independent (r,q) pairs. */
#pragma omp parallel for collapse(2) private(p,s) if (_PB_NR * _PB_NQ > 1)
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++)
    {
      /* Pointer to the contiguous row A[r][q][:] to simplify indexing
         and improve compiler alias analysis. */
      DATA_TYPE * restrict A_rq = A[r][q];

      /* Per-(r,q) temporary accumulation buffer.
         Size is NP (compile-time upper bound); we only use 0.._PB_NP-1. */
      DATA_TYPE sum_local[NP];

      /* Initialize the accumulation buffer. */
      for (p = 0; p < _PB_NP; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* Compute: sum_local[p] = sum_s A_rq[s] * C4[s][p] */
      for (s = 0; s < _PB_NP; s++)
      {
        const DATA_TYPE a_rqs = A_rq[s];
        const DATA_TYPE * restrict C4_row = &C4[s][0];

        /* Unroll the p-loop by 4 for better ILP and vectorization. */
        int p_unroll;
        int limit = _PB_NP & ~3; /* largest multiple of 4 <= _PB_NP */

        for (p_unroll = 0; p_unroll < limit; p_unroll += 4)
        {
          sum_local[p_unroll    ] += a_rqs * C4_row[p_unroll    ];
          sum_local[p_unroll + 1] += a_rqs * C4_row[p_unroll + 1];
          sum_local[p_unroll + 2] += a_rqs * C4_row[p_unroll + 2];
          sum_local[p_unroll + 3] += a_rqs * C4_row[p_unroll + 3];
        }

        /* Remainder loop for any leftover elements. */
        for (p = limit; p < _PB_NP; p++)
          sum_local[p] += a_rqs * C4_row[p];
      }

      /* Write the accumulated result back into A. */
      for (p = 0; p < _PB_NP; p++)
        A_rq[p] = sum_local[p];
    }

  /* Maintain the observable final state of "sum":
     In the original kernel, on exit, sum[p] equals A[_PB_NR-1][_PB_NQ-1][p]. */
  if (_PB_NR > 0 && _PB_NQ > 0)
  {
    const int r_last = _PB_NR - 1;
    const int q_last = _PB_NQ - 1;
    for (p = 0; p < _PB_NP; p++)
      sum[p] = A[r_last][q_last][p];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}

