   *       sum[p] += A[r][q][s] * C4[s][p];
   *
   * For each fixed (r, q, p), the updates over s still occur in
   * strictly increasing s order, so the floating‑point accumulation
   * sequence for that element is unchanged (bit‑identical result),
   * while accesses to C4 and the sum buffer are now unit‑stride. */
#pragma omp parallel private(r, q, p, s)
  {
    /* Per-thread accumulation buffer.  Using a VLA keeps the memory
     * footprint modest and sized exactly to the active problem size
     * inside the timed region. */
    DATA_TYPE sum_local[_PB_NP];

#pragma omp for collapse(2) schedule(static)
    for (r = 0; r < _PB_NR; r++)
      for (q = 0; q < _PB_NQ; q++)
      {
        /* Shortcut pointers for better readability and to help the
         * compiler with vectorization. */
        DATA_TYPE *restrict a_rq   = &A[r][q][0];
        DATA_TYPE *restrict sumptr = sum_local;

        /* Initialize accumulation buffer for this (r, q). */
        for (p = 0; p < _PB_NP; p++)
          sumptr[p] = SCALAR_VAL(0.0);

        /* Matrix–vector style accumulation:
         *   sum[p] += A[r][q][s] * C4[s][p]
         * with unit‑stride accesses in both `sum_local` and the current
         * row of C4. */
        for (s = 0; s < _PB_NP; s++)
        {
          const DATA_TYPE a_rq_s = a_rq[s];
          const DATA_TYPE *restrict c4_row = &C4[s][0];

          #pragma GCC ivdep
          for (p = 0; p < _PB_NP; p++)
            sumptr[p] += a_rq_s * c4_row[p];
        }

        /* Write the result back to A[r][q][p].  This is equivalent to
         * the original final loop over p. */
        #pragma GCC ivdep
        for (p = 0; p < _PB_NP; p++)
          a_rq[p] = sumptr[p];
      }
  }
#pragma endscop

  /* Preserve the original meaning of `sum`: after the kernel, it
   * contained the values computed for the last (r, q) pair processed
   * by the loops, which are exactly A[_PB_NR-1][_PB_NQ-1][:].  This
   * array is not used by the benchmark, but keeping it identical
   * maintains strict functional equivalence. */
  if (sum != NULL && _PB_NR > 0 && _PB_NQ > 0)
  {
    DATA_TYPE *restrict last_a = &A[_PB_NR-1][_PB_NQ-1][0];

    for (p = 0; p < _PB_NP; p++)
      sum[p] = last_a[p];
  }
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}
