#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "doitgen.h"


/* Array initialization. */
static
void init_array(int nr, int nq, int np,
		DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np))
{
  int i, j, k;

  /* Precompute 1/np as a scalar of the correct type to replace
     expensive floating-point divisions by cheaper multiplications. */
  const DATA_TYPE inv_np = SCALAR_VAL(1.0) / (DATA_TYPE)np;

  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++) {
      const int ij = i * j;
      for (k = 0; k < np; k++)
        /* Original formula:
             A[i][j][k] = (DATA_TYPE)((i*j + k) % np) / np;
           Rewritten as:
             tmp = (i*j + k) % np;
             A = (DATA_TYPE)tmp * inv_np;
           This preserves exact semantics (same integer mod, same
           order of operations per element) but uses one division per
           array, not per element. */
        A[i][j][k] = (DATA_TYPE)((ij + k) % np) * inv_np;
    }

  for (i = 0; i < np; i++)
    for (j = 0; j < np; j++) {
      const int ij = i * j;
      /* Same optimization as above:
           C4[i][j] = (DATA_TYPE)(i*j % np) / np;
           -> (DATA_TYPE)((i*j) % np) * inv_np; */
      C4[i][j] = (DATA_TYPE)(ij % np) * inv_np;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;
  (void)nr;   /* nr, nq are not needed inside the optimized kernel. */
  (void)nq;
  (void)sum;  /* The original temporary array is no longer used. */

  /* NOTE ON SEMANTICS:
     The original kernel computes, for each (r,q), and for each p:
       sum[p] = sum_{s} A[r][q][s] * C4[s][p]
       A[r][q][p] = sum[p]
     Our transformed version:
       1. Initializes all sum[p] to 0 once per (r,q).
       2. Loops over s on the outside and p on the inside:
            sum[p] += A[r][q][s] * C4[s][p]
       3. Writes back A[r][q][p] = sum[p].
     For each fixed (r,q,p), the sequence of terms accumulated into
     sum[p] is still in strictly increasing s order, so the
     floating‑point reduction order for each output element is
     unchanged. Only the interleaving across different p changes.
     Thus each A[r][q][p] is bit‑identical to the original code. */

#pragma scop
  /* Parallelize across r and q. Each (r,q) slice of A is independent,
     so there are no cross‑iteration dependencies. OpenMP pragmas are
     ignored when the code is compiled without -fopenmp. */
#pragma omp parallel for collapse(2) private(p, s) schedule(static)
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++) {

      /* Use a thread‑private temporary buffer for the result of the
         matrix–matrix product for this (r,q). Using a local array
         avoids races and false sharing on the original 'sum' array.
         NP is the compile‑time problem size bound (from doitgen.h). */
      DATA_TYPE sum_local[NP];

      /* Pointer to the contiguous 1D slice A[r][q][0..NP-1].
         Using a pointer improves compiler optimization and keeps
         address calculations simple. */
      DATA_TYPE *restrict A_rq = &A[r][q][0];

      /* 1. Initialize accumulation buffer to zero. */
#pragma omp simd
      for (p = 0; p < _PB_NP; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* 2. Compute:
             sum_local[p] = sum_s A[r][q][s] * C4[s][p]
         We switch the original p/s loop nesting to s/p, which:
           - reads A[r][q][s] only once per s instead of once per (p,s),
           - walks C4 in row‑major order (C4[s][p]) for better locality,
           - reuses sum_local[p] in cache across all s iterations. */
      for (s = 0; s < _PB_NP; s++) {
        const DATA_TYPE a_rqs = A_rq[s];
        DATA_TYPE *restrict C4_row = &C4[s][0];

#pragma omp simd
        for (p = 0; p < _PB_NP; p++)
          sum_local[p] += a_rqs * C4_row[p];
      }

      /* 3. Copy the accumulated result back into A[r][q][p]. */
#pragma omp simd
      for (p = 0; p < _PB_NP; p++)
        A_rq[p] = sum_local[p];
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

